// FAIL CLOSED AT LOAD. A profile is only evidence while it is the evidence that was
// certified: each digest is recomputed here, so a hand-edited entry throws before the gate
// can certify anything against it, rather than silently widening what counts as stock.
for (const profile of STOCK_MANAGED_OBJECT_PROFILES) {
  if (profile.objects.length !== profile.objectCount) {
    throw new Error(`certified profile ${profile.id} declares ${profile.objectCount} objects but carries ${profile.objects.length}`);
  }
  const digest = createHash("sha256")
    .update(profile.objects.map((o) => `${o.schema}|${o.kind}|${o.name}|${o.owner}|${o.fingerprint}`).sort().join("\n"), "utf8")
    .digest("hex");
  if (digest !== profile.digest) {
    throw new Error(
      `certified profile ${profile.id} does not match its certified digest (computed ${digest}, expected ${profile.digest}). ` +
      "Re-certify it from a known-stock capture; do not adjust the digest to match an edit.",
    );
  }
}
